/**
 * Recurring-issue rules: authorization, the per-plan rule quota and pausing.
 * The job in `src/server/jobs/recurring-issue-job.ts` files the issues.
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import { orgResource, projectResource, requireFound } from "./_support";
import type { CreateRecurringIssueInput } from "@/schemas/recurring-issue";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

export async function createRecurringIssue(
  actor: Actor,
  input: CreateRecurringIssueInput,
): Promise<RecurringIssue> {
  const parsed = createRecurringIssueSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(parsed.orgId, parsed.projectId),
    "Project",
    parsed.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  if (parsed.assigneeId !== null) {
    const assignee = await memberRepo.findMember(parsed.orgId, parsed.assigneeId);
    if (!assignee || assignee.status !== "active") {
      throw new Error(`Assignee ${parsed.assigneeId} is not an active member`);
    }
  }

  const org = requireFound(
    await orgRepo.findOrgById(parsed.orgId),
    "Organization",
    parsed.orgId,
  );
  const used = await recurringRepo.countRecurringIssues(parsed.orgId);
  if (wouldExceedLimit(org.plan, "recurringIssues", used)) {
    throw new Error(`Plan ${org.plan} allows no more recurring issues`);
  }

  return recurringRepo.insertRecurringIssue(parsed, actor.userId);
}

export async function setRecurringIssuePaused(
  actor: Actor,
  input: { orgId: OrgId; recurringIssueId: string; paused: boolean },
): Promise<RecurringIssue> {
  assertOrgScope(actor, input.orgId);

  const rule = requireFound(
    await recurringRepo.findRecurringIssueById(input.orgId, input.recurringIssueId),
    "RecurringIssue",
    input.recurringIssueId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, rule.projectId),
    "Project",
    rule.projectId,
  );
  assertCan(actor, "issue:create", projectResource(project));

  return recurringRepo.updateRecurringIssue(input.orgId, rule.id, {
    paused: input.paused,
  });
}

export async function listRecurringIssues(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "issue:read", orgResource(orgId));
  return recurringRepo.listRecurringIssues(orgId);
}
EOF
cat > src/server/jobs/recurring-issue-job.ts <<'EOF'
/**
 * Files the latest started occurrence of every non-paused recurring-issue rule
 * as an ordinary issue, on behalf of the rule's creator.
 */
import { can } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import { createLogger } from "@/lib/logger";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import { projectResource } from "@/server/services/_support";
import { createIssue } from "@/server/services/issue-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

const logger = createLogger("recurring-issue-job");

export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringRepo.listActiveRecurringIssues();

    for (const rule of rules) {
      try {
        if (await processRule(rule, now)) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("recurring issue failed", {
          recurringIssueId: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

async function processRule(rule: RecurringIssue, now: Date): Promise<boolean> {
  const latest = latestOccurrence(rule, now);
  if (latest === null) return false;
  if (rule.lastOccurrenceOn !== null && latest <= rule.lastOccurrenceOn) return false;

  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (!project || isArchived(project)) return false;

  const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
  const actor: Actor | null =
    creator && creator.status === "active"
      ? { userId: rule.createdBy, orgId: rule.orgId, role: creator.role }
      : null;
  if (!actor || !can(actor, "issue:create", projectResource(project))) {
    await recurringRepo.updateRecurringIssue(rule.orgId, rule.id, { paused: true });
    return false;
  }

  let assigneeId = rule.assigneeId;
  if (assigneeId !== null) {
    const assignee = await memberRepo.findMember(rule.orgId, assigneeId);
    if (!assignee || assignee.status !== "active") assigneeId = null;
  }

  await createIssue(actor, {
    orgId: rule.orgId,
    projectId: rule.projectId,
    title: `${rule.title} (${latest})`,
    description: null,
    status: "backlog",
    priority: rule.priority,
    assigneeId,
    parentId: null,
    estimate: null,
    dueAt: null,
    labelIds: [],
  });

  await recurringRepo.updateRecurringIssue(rule.orgId, rule.id, {
    lastOccurrenceOn: latest,
  });
  return true;
}

/** The local calendar date (`YYYY-MM-DD`) of `now` in `timeZone`. */
function localDate(now: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(now);
  const get = (type: string) => parts.find((p) => p.type === type)?.value ?? "";
  return `${get("year")}-${get("month")}-${get("day")}`;
}

function toUtcMs(date: string): number {
  const [y, m, d] = date.split("-").map(Number);
  return Date.UTC(y!, m! - 1, d!);
}

function fromUtcMs(ms: number): string {
  return new Date(ms).toISOString().slice(0, 10);
}

/**
 * The latest occurrence day that has started by `now` in the rule's zone, or
 * null. A day has started once the local date has reached it.
 */
export function latestOccurrence(rule: RecurringIssue, now: Date): string | null {
  const today = localDate(now, rule.timezone);
  if (today < rule.startsOn) return null;

  let ms = toUtcMs(today);
  if (rule.cadence === "weekly" && rule.weekday !== null) {
    const isoWeekday = ((new Date(ms).getUTCDay() + 6) % 7) + 1;
    ms -= ((isoWeekday - rule.weekday + 7) % 7) * MS_PER_DAY;
  }
  const candidate = fromUtcMs(ms);
  return candidate >= rule.startsOn ? candidate : null;
}
